import{_ as t,o as a,c as n,a0 as r}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"F2F Cross-Border: Fiat-to-Fiat Settlement Platform","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function i(s,e,d,c,h,l){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="f2f-cross-border-fiat-to-fiat-settlement-platform" tabindex="-1">F2F Cross-Border: Fiat-to-Fiat Settlement Platform <a class="header-anchor" href="#f2f-cross-border-fiat-to-fiat-settlement-platform" aria-label="Permalink to &quot;F2F Cross-Border: Fiat-to-Fiat Settlement Platform&quot;">​</a></h1><p>A non-custodial orchestration layer over licensed payment rails, with a verifiable compliance trail anchored on Hedera.</p><p>DDiB 2026 · University of Zurich</p><blockquote><p>This repo now serves a small collection, not one page: <code>/</code> is a collection hub, this project lives at <code>/cross-border</code>, and a sister project, <strong>OnChain Oversight</strong>, extends the same trust-layer philosophy to a regulator-facing audience. See <a href="./project/milestones.html">Milestones</a> for the full timeline of what was built where and when.</p></blockquote><h2 id="what-this-proves" tabindex="-1">What this proves <a class="header-anchor" href="#what-this-proves" aria-label="Permalink to &quot;What this proves&quot;">​</a></h2><p>The licensed parties move the money and perform the checks. We never hold funds. Our contribution is that each compliance decision — and now each settlement-routing decision — is hashed and anchored with a consensus timestamp, so &quot;the checks passed at this moment&quot; becomes independently verifiable rather than asserted.</p><h2 id="live-evidence-hedera-testnet-verified-end-to-end" tabindex="-1">Live evidence (Hedera testnet, verified end to end) <a class="header-anchor" href="#live-evidence-hedera-testnet-verified-end-to-end" aria-label="Permalink to &quot;Live evidence (Hedera testnet, verified end to end)&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Topic</td><td><a href="https://hashscan.io/testnet/topic/0.0.9617780" target="_blank" rel="noreferrer">0.0.9617780</a></td></tr><tr><td>Compliance anchor</td><td>sequence #2</td></tr><tr><td>Quote anchor</td><td>sequence #3</td></tr><tr><td>Routing decision anchor (small amount → hedera)</td><td>sequence #4</td></tr><tr><td>Routing decision anchor (large amount → ethereum, unexecuted)</td><td>sequence #5</td></tr><tr><td>Live liquidity check</td><td>$26,510,503 (real-time SaucerSwap <code>/stats</code> read, not simulated)</td></tr><tr><td>Completion topic (2-of-2 partner-keyed submit key)</td><td><a href="https://hashscan.io/testnet/topic/0.0.9753239" target="_blank" rel="noreferrer">0.0.9753239</a></td></tr><tr><td>Intermediary settlement account (2-of-2 threshold key)</td><td><a href="https://hashscan.io/testnet/account/0.0.9753237" target="_blank" rel="noreferrer">0.0.9753237</a></td></tr></tbody></table><p>Every anchor above was independently verified via a public Mirror Node — not our own database — and the tamper test (edit a record, recompute, compare) correctly flips MATCH to MISMATCH.</p><h2 id="which-hedera-services-this-actually-uses" tabindex="-1">Which Hedera services this actually uses <a class="header-anchor" href="#which-hedera-services-this-actually-uses" aria-label="Permalink to &quot;Which Hedera services this actually uses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>What it&#39;s used for</th></tr></thead><tbody><tr><td><strong>Hedera Consensus Service (HCS)</strong></td><td>Compliance, quote, and routing-decision anchoring, plus the completion message, each a hashed pointer message with a consensus timestamp neither party controls</td></tr><tr><td><strong>Hedera Token Service (HTS)</strong></td><td>The real stablecoin transfer executed on Hedera when a corridor routes there</td></tr><tr><td><strong>Hedera Schedule Service (HSS)</strong></td><td>The completion anchor: a <code>ScheduleCreateTransaction</code> that only executes once both the source-side and destination-side partner have independently signed, gated by a 2-of-2 threshold key, not our own operator key</td></tr><tr><td><strong>Mirror Node REST API</strong></td><td>Independent, public verification of every anchor above, by sequence number and by transaction ID, never through our own database</td></tr></tbody></table><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to &quot;Run it&quot;">​</a></h2><pre><code>npm install
cp .env.example .env      # add your own testnet credentials
npm test                  # 14 unit tests, no network, ~1 second
node demo-modular.mjs     # compliance + quote anchoring, tamper proof
node demo-router.mjs 100      # routes to hedera, executes a real transfer
node demo-router.mjs 50000    # routes to ethereum, honestly unexecuted
</code></pre><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><pre><code>backend/services/hedera/        the trust anchor — always Hedera
  client.mjs      connection + key parsing (ED25519 or ECDSA)
  hashing.mjs      canonical hashing + HMAC pseudonymous references
  topic.mjs        HCS topic creation/reuse (main + completion)
  anchor.mjs        compliance / quote / routing-decision anchoring
  thresholdAccount.mjs  2-of-2 threshold-key intermediary account
  scheduleAnchor.mjs     HSS completion anchor, gated by both partners
  verify.mjs         Mirror Node read + tamper detection

backend/services/settlement/    which chain actually moves the value
  corridorConfig.mjs   partner chain support, compliant stablecoins
  liquidity.mjs         real Hedera stablecoin liquidity depth (SaucerSwap)
  corridorRouter.mjs    the routing decision (Hedera preferred, falls
                        back only when the partner needs it or the
                        amount exceeds Hedera&#39;s safe depth)
  execute.mjs            real execution on Hedera; honestly labeled
                          non-execution elsewhere (see below)
</code></pre><h2 id="why-the-settlement-chain-isn-t-always-hedera" tabindex="-1">Why the settlement chain isn&#39;t always Hedera <a class="header-anchor" href="#why-the-settlement-chain-isn-t-always-hedera" aria-label="Permalink to &quot;Why the settlement chain isn&#39;t always Hedera&quot;">​</a></h2><p>Hedera is our trust layer — every compliance and routing decision is anchored there regardless of which chain actually settles the value. But Hedera&#39;s stablecoin liquidity is real but thin (tens of millions, not billions), so large transfers are routed to deeper liquidity (Ethereum, Solana) once the partner supports it. The decision itself is anchored too, so &quot;why did this go to Ethereum?&quot; is answerable by anyone, not just us.</p><h2 id="what-is-genuinely-executed-vs-honestly-not" tabindex="-1">What is genuinely executed vs. honestly not <a class="header-anchor" href="#what-is-genuinely-executed-vs-honestly-not" aria-label="Permalink to &quot;What is genuinely executed vs. honestly not&quot;">​</a></h2><ul><li><strong>Hedera</strong>: fully real. A genuine HTS token transfer on testnet, a real transaction ID, verifiable on HashScan.</li><li><strong>Ethereum / Solana</strong>: the routing <em>decision</em> is real and anchored, but actual execution is deliberately left unexecuted and clearly labeled — we have no funded testnet credentials for those chains yet. This is intentional: fabricating a transaction reference for a chain we cannot actually reach would be exactly the &quot;fake blockchain demo&quot; risk this project is designed to avoid. Multi-chain execution is scoped as future work (see <code>docs/project/roadmap.md</code>), not simulated as if it already worked.</li></ul><h2 id="what-never-goes-on-chain" tabindex="-1">What never goes on-chain <a class="header-anchor" href="#what-never-goes-on-chain" aria-label="Permalink to &quot;What never goes on-chain&quot;">​</a></h2><p>Only a SHA-256 hash and a pseudonymous (HMAC&#39;d) reference. No name, no IBAN, no amount, no KYC document. The plaintext stays off-chain with the licensed party. See <code>docs/legal/compliance-data.md</code> for the full privacy boundary and canonicalisation rules.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Sandbox and testnet. Not a payment institution, not a CASP, not a custodian. See <code>docs/legal/why-this-is-legal.md</code>.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>All rights reserved. See <code>LICENSE</code>.</p>`,25)])])}const p=t(o,[["render",i]]);export{m as __pageData,p as default};
